import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";

const SplashScreen = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setTimeout(() => {
      navigate("/login");   // ✅ IMPORTANT FIX
    }, 5000); // 5 sec (test ke liye short rakho)

    return () => clearTimeout(timer);
  }, [navigate]);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h1 style={styles.title}>🎓 EduSaarthi</h1>

        <p style={styles.subtitle}>
          AI-Powered Academic Companion
        </p>

        <p style={styles.desc}>
          A next-generation learning platform built for modern university students.
          Access study material, notices, and an intelligent chatbot.
        </p>

        <div style={styles.loader}></div>
      </div>
    </div>
  );
};

export default SplashScreen;

const styles = {
  container: {
    height: "100vh",
    background: "#0f172a",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    color: "white",
  },
  card: {
    textAlign: "center",
  },
  title: {
    fontSize: "30px",
    color: "#38bdf8",
  },
  subtitle: {
    color: "#22c55e",
  },
  desc: {
    fontSize: "14px",
    marginTop: "10px",
  },
  loader: {
    marginTop: "20px",
    border: "4px solid #334155",
    borderTop: "4px solid #38bdf8",
    borderRadius: "50%",
    width: "40px",
    height: "40px",
    animation: "spin 1s linear infinite",
  },
};
